import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

/** Reconciles a ledger using constant heap and bounded external sorting. */
public final class Reconciler {
    public record AccountSummary(
            String account,
            long count,
            long total,
            long firstSequence,
            long lastSequence,
            long firstTimestamp,
            long lastTimestamp,
            long checksum) {
    }

    public record Report(long eventCount, java.util.List<AccountSummary> accounts) {
        public String render() {
            StringBuilder out = new StringBuilder();
            out.append("events|").append(eventCount).append('\n');
            for (AccountSummary account : accounts) {
                appendSummary(out, account);
            }
            return out.toString();
        }

        private static void appendSummary(StringBuilder out, AccountSummary account) {
            out.append(account.account()).append('|')
                    .append(account.count()).append('|')
                    .append(account.total()).append('|')
                    .append(account.firstSequence()).append('|')
                    .append(account.lastSequence()).append('|')
                    .append(account.firstTimestamp()).append('|')
                    .append(account.lastTimestamp()).append('|')
                    .append(account.checksum()).append('\n');
        }
    }

    private static final class AccountState {
        private String account;
        private long count;
        private long total;
        private long firstSequence = -1;
        private long lastSequence;
        private long firstTimestamp;
        private long lastTimestamp;
        private long checksum = 0x5deece66dL;
    }

    /**
     * Reconciles the log and writes a complete report to a temporary file.
     *
     * Validation and account aggregation are completed before the caller exposes any
     * output. Events are externally sorted by account, timestamp, then sequence. This
     * satisfies the checksum order without retaining the event stream in the heap.
     */
    public static Path reconcileToReport(Path input) throws IOException {
        Path sorted = Files.createTempFile("ledger-reconcile-sorted-", ".tmp");
        Path report = Files.createTempFile("ledger-reconcile-report-", ".tmp");
        try {
            long eventCount = validate(input);
            runExternalSort(input, sorted);
            writeReport(sorted, report, eventCount);
            return report;
        } catch (Throwable failure) {
            try {
                Files.deleteIfExists(report);
            } catch (IOException ignored) {
                // Preserve the original reconciliation failure.
            }
            throw failure;
        } finally {
            Files.deleteIfExists(sorted);
        }
    }

    /** Kept for compatibility with the original in-memory API. */
    public static Report reconcile(Path input) throws IOException {
        Path report = reconcileToReport(input);
        try {
            return parseReport(report);
        } finally {
            Files.deleteIfExists(report);
        }
    }

    private static long validate(Path input) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(input, StandardCharsets.UTF_8)) {
            long lineNumber = 0;
            long previous = -1;
            String line;
            while ((line = reader.readLine()) != null) {
                lineNumber++;
                EventLog.Event event = EventLog.parse(line, lineNumber);
                if (event.sequence() <= previous) {
                    throw new IllegalArgumentException("sequence order at line " + lineNumber);
                }
                previous = event.sequence();
            }
            if (lineNumber == 0) {
                throw new IllegalArgumentException("empty log");
            }
            return lineNumber;
        }
    }

    private static void runExternalSort(Path input, Path output) throws IOException, InterruptedException {
        ProcessBuilder builder = new ProcessBuilder(
                "sort", "-t", "|",
                "-k", "4,4",
                "-k", "2,2n",
                "-k", "1,1n",
                "-S", "8M",
                "--parallel=2",
                "-o", output.toString(),
                input.toString());
        builder.environment().put("LC_ALL", "C");
        Process process = builder.start();
        int status = process.waitFor();
        if (status != 0) {
            throw new IOException("external sort failed with status " + status);
        }
    }

    private static void writeReport(Path sorted, Path report, long eventCount)
            throws IOException, InterruptedException {
        try (BufferedReader reader = Files.newBufferedReader(sorted, StandardCharsets.UTF_8);
             BufferedWriter writer = Files.newBufferedWriter(report, StandardCharsets.UTF_8)) {
            writer.write("events|");
            writer.write(Long.toString(eventCount));
            writer.write('\n');

            AccountState state = new AccountState();
            long lineNumber = 0;
            String line;
            while ((line = reader.readLine()) != null) {
                lineNumber++;
                EventLog.Event event = EventLog.parse(line, lineNumber);
                if (state.account == null) {
                    state.account = event.account();
                } else if (!state.account.equals(event.account())) {
                    writeSummary(writer, state);
                    state = new AccountState();
                    state.account = event.account();
                }
                apply(state, event);
            }
            if (state.account != null) {
                writeSummary(writer, state);
            }
        }
    }

    private static void apply(AccountState state, EventLog.Event event) {
        long sequence = event.sequence();
        long timestamp = event.timestamp();
        long amount = event.amount();

        if (state.count == 0) {
            state.firstSequence = sequence;
            state.firstTimestamp = timestamp;
        }
        if (sequence < state.firstSequence) {
            state.firstSequence = sequence;
            state.firstTimestamp = timestamp;
        }
        if (state.count == 0 || sequence > state.lastSequence) {
            state.lastSequence = sequence;
            state.lastTimestamp = timestamp;
        }

        state.count++;
        state.total = Math.addExact(state.total, amount);
        long value = 31L * state.checksum + sequence;
        value = 31L * value + timestamp;
        state.checksum = 31L * value + amount;
    }

    private static void writeSummary(BufferedWriter writer, AccountState state) throws IOException {
        writer.write(state.account);
        writer.write('|');
        writer.write(Long.toString(state.count));
        writer.write('|');
        writer.write(Long.toString(state.total));
        writer.write('|');
        writer.write(Long.toString(state.firstSequence));
        writer.write('|');
        writer.write(Long.toString(state.lastSequence));
        writer.write('|');
        writer.write(Long.toString(state.firstTimestamp));
        writer.write('|');
        writer.write(Long.toString(state.lastTimestamp));
        writer.write('|');
        writer.write(Long.toString(state.checksum));
        writer.write('\n');
    }

    private static Report parseReport(Path report) throws IOException {
        try (BufferedReader reader = Files.newBufferedReader(report, StandardCharsets.UTF_8)) {
            String header = reader.readLine();
            if (header == null || !header.startsWith("events|")) {
                throw new IllegalStateException("invalid generated report");
            }
            long eventCount = Long.parseLong(header.substring(7));
            java.util.List<AccountSummary> accounts = new java.util.ArrayList<>();
            java.util.Map<String, AccountSummary> byName = new java.util.HashMap<>();
            String line;
            while ((line = reader.readLine()) != null) {
                String[] fields = line.split("\\|", -1);
                if (fields.length != 8) {
                    throw new IllegalStateException("invalid generated report line");
                }
                AccountSummary summary = new AccountSummary(
                        fields[0], Long.parseLong(fields[1]), Long.parseLong(fields[2]),
                        Long.parseLong(fields[3]), Long.parseLong(fields[4]),
                        Long.parseLong(fields[5]), Long.parseLong(fields[6]),
                        Long.parseLong(fields[7]));
                if (byName.put(summary.account(), summary) != null) {
                    throw new IllegalStateException("duplicate generated account");
                }
                accounts.add(summary);
            }
            return new Report(eventCount, accounts);
        }
    }

    private Reconciler() {
    }
}
